int main(int argc,char**argv){g_test_init(&argc,&argv,nullptr);gimp_test_utils_set_gimp3_directory("GIMP_TESTING_ABS_TOP_SRCDIR","app/tests/gimpdir");gimp=gimp_init_for_testing();g_object_set(gimp->config,"painter-canvas-ui",TRUE,nullptr);gboolean oncanvas=FALSE;g_object_get(gimp->config,"painter-canvas-ui",&oncanvas,nullptr);g_assert_true(oncanvas);g_test_add_func("/paired/repeated-live-reconfigure",repeated_history);g_test_add_func("/paired/update-coherent",observer_coherence);g_test_add_func("/paired/cancel-preserves-redo",cancel_redo);g_test_add_func("/paired/frozen-preflight",frozen_failure);g_test_add_func("/paired/allocation-before-publication",paired_allocation_failure);g_test_add_func("/paired/destroyed-owner",destroyed_owner);g_test_add_func("/paired/replaced-owner",replaced_owner);g_test_add_func("/paired/group-shared-owner",grouped_history);g_test_add_func("/paired/active-pending",active_rejection);g_test_add_func("/paired/idle-open-history-rejection",idle_open_history_rejection);g_test_add_func("/paired/empty-cancel",empty_cancel);g_test_add_func("/paired/no-undo-commit",no_undo_commit);g_test_add_func("/paired/begin-allocation",begin_failure);g_test_add_func("/paired/native-continuation-coordinates",native_coordinates);g_test_add_func("/paired/buffer-observer-coherent",buffer_coherence);g_test_add_func("/paired/cancel-observer-coherent",cancel_observers);g_test_add_func("/paired/failure-observer-coherent",failure_observers);g_test_add_func("/paired/retained-memory",retained_memory);int result=g_test_run();gimp_test_utils_set_gimp3_directory("GIMP_TESTING_ABS_TOP_BUILDDIR","app/tests/gimpdir-output");gimp_exit(gimp,TRUE);return result;}

#endif
